def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    change_ratio = (change / v1) * 100

    return {
        "value": change_ratio,
        "trace": {
            "starting_value_2017": v1,
            "ending_value_2018": v2,
            "absolute_change": change,
            "change_ratio_percentage": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
